package com.coraline.tycoon;
import java.util.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.eventbus.api.SubscribeEvent;
/** Operator-only development surface. Never invoked by normal care/profit code. */
@Mod.EventBusSubscriber(modid="coraline")
public final class TycoonDebug {
    private static final String[][] CONTROLS={
        {"Coraline Tycoon — Food, Trust & Neglect","open_food"},
        {"Coraline Tycoon — Phase 2","open_phase_two"},
        {"Grant World Weaver","weaver"},{"Grant Void Heart","heart"},{"Force entrance capability / lost-door recovery","door"},{"Activate test world","activate"},{"Enter personal world","enter"},{"Return to Overworld","return"},{"Show owner/region","owner"},{"Validate platform (no build deletion)","platform"},{"Test void-fall recovery","fall"},{"Show relocation validation","relocation"},
        {"Give 64 Void Power","power"},{"Inspect crafting recipes","recipes"},{"Set debug Soul Essence to 100","soul"},{"Show progression","progress"},{"Grant unique test milestone","milestone"},{"Reset debug milestone only","reset_progress"},{"Recover phone (invalidate prior phone)","phone"},{"Open real Work Desk shop nearby","shop"},
        {"Buy Orphan Bed normally","buy:orphan_bed"},{"Buy Food Table normally","buy:orphan_food_table"},{"Buy Fridge normally","buy:orphan_fridge"},{"Buy Water Station normally","buy:water_station"},{"Buy decoration normally","buy:orphan_rug"},{"Show purchase validation","purchase"},
        {"Generate agency safely","agency"},{"Teleport to agency","agency_tp"},{"Request physical inspection","inspect"},{"Force inspection approval (debug)","pass"},{"Force inspection rejection (debug)","fail"},{"Show physical capacity / bed count","capacity"},{"Reset placement cooldown","cooldown"},{"Spawn test resident in valid bed","spawn"},{"Show reputation","reputation"},
        {"Select nearest resident","select"},{"Show hidden traits","traits"},{"Set Hunger to 10","hunger"},{"Set Thirst to 10","thirst"},{"Set Neglect to 76","neglect"},{"Set debug Comfort to 0","comfort"},{"Trigger meal request","meal"},{"Force self-feed attempt","self_feed"},{"Empty owned fridge into inventory","empty_fridge"},{"Trigger water request","water"},{"Trigger catch request","catch"},{"Trigger item request","item"},{"Trigger designated toy incident","incident"},{"Test Forgive","forgive"},{"Test cleanup consequence","punish"},{"Force runaway (test child only)","runaway"},{"Force custody (test children only)","custody"},{"Test deprivation (test child only)","critical"},{"Show schedule / task","task"},
        {"Repair test platform (preserve player builds)","reset_platform"},{"Move entrance two blocks (real validation)","relocate_test"},{"Test selected child's sleep schedule","schedule"},
        {"Save and read back durable owner checkpoint","persistence"},{"Simulate story inventory reset on copies","reset_simulation"},{"Validate permanent progression preserved","preserved"},{"Inspect owner bindings / duplicate entities","duplicates"}
    };
    public static ListTag controls(){var list=new ListTag();for(var control:CONTROLS){var n=new CompoundTag();n.putString("Label",control[0]);n.putString("Action",control[1]);list.add(n);}return list;}
    @SubscribeEvent public static void commands(net.minecraftforge.event.RegisterCommandsEvent e){e.getDispatcher().register(net.minecraft.commands.Commands.literal("coraline_tycoon").requires(s->s.hasPermission(2)).executes(c->{TycoonNetwork.open(c.getSource().getPlayerOrException(),"debug",null);return 1;}));}
    private static TycoonData.Resident selected(ServerPlayer p){var h=TycoonWorld.home(p);if(h.state.hasUUID("DebugSelected"))return h.residents.get(h.state.getUUID("DebugSelected"));return null;}
    public static String run(ServerPlayer p,String action){if(!p.hasPermissions(2))return "Operator permission required.";var h=TycoonWorld.home(p);var n=h.state;var r=selected(p);String result="Done.";
        if(action.startsWith("buy:"))return TycoonShop.buy(p,action.substring(4));
        switch(action){case "weaver"->TycoonWorld.deliver(p,new ItemStack(TycoonContent.WEAVER.get()));case "heart"->TycoonWorld.deliver(p,new ItemStack(com.coraline.rebirth.RebirthItems.VOID_HEART.get()));case "door"->result=TycoonWorld.giveDoor(p,true)?"Fresh entrance capability issued; stale copies no longer place.":"Placeable entrance still exists or inventory full.";
        case "activate"->{if(TycoonWorld.prepare(p)){n.putBoolean("Activated",true);n.putBoolean("DebugActivation",true);}else return "Platform blocked; no blocks overwritten.";}
        case "enter"->TycoonWorld.enter(p);case "return"->TycoonWorld.leave(p);case "owner"->result=h.owner+" region "+h.slot+" @ "+h.center().toShortString();case "platform"->result="Built="+n.getBoolean("PlatformBuilt")+"; dimensions 8 x 8. Existing player construction is never reset by this control.";case "fall"->{if(p.serverLevel().dimension().equals(TycoonWorld.KEY))p.teleportTo(p.getX(),h.center().getY()-14,p.getZ());}case "relocation"->result="Registered bed="+TycoonWorld.registeredBed(p)+"; radius="+TycoonConfig.BED_RADIUS.get()+"; entrance="+h.entrance();
        case "power"->TycoonWorld.deliver(p,new ItemStack(TycoonContent.VOID_POWER.get(),64));case "recipes"->result="Weaver: 1 Void Heart, 4 iron, 3 string. Void Power: amethyst + coal + redstone -> 4.";case "soul"->{n.putLong("SoulEssence",100);n.putBoolean("DebugSoulBalance",true);}case "progress"->result="Level "+h.level()+", XP "+h.xp()+", milestones "+n.getCompound("Milestones");case "milestone"->h.milestone("debug_test",10);case "reset_progress"->{if(n.getCompound("Milestones").getBoolean("debug_test")){n.getCompound("Milestones").remove("debug_test");n.putInt("ProgressXP",Math.max(0,h.xp()-10));}}
        case "phone"->result=TycoonShop.recoverPhone(p);case "shop"->{var at=h.center().offset(1,0,-1);if(p.serverLevel().dimension().equals(TycoonWorld.KEY)&&p.distanceToSqr(at.getCenter())<64)TycoonNetwork.open(p,"desk",at);else result="Stand beside your real Work Desk.";}case "purchase"->result="Void Power="+TycoonShop.count(p,TycoonContent.VOID_POWER.get())+", free slot="+p.getInventory().getFreeSlot();case "agency"->TycoonAgency.contact(p);case "agency_tp"->{if(n.getBoolean("AgencyBuilt")){var at=TycoonWorld.landing(p.server.overworld(),net.minecraft.core.BlockPos.of(n.getLong("Agency")).south(8).above());if(at!=null)p.teleportTo(p.server.overworld(),at.getX()+.5,at.getY(),at.getZ()+.5,p.getYRot(),0);}}case "inspect"->TycoonAgency.request(p);
        case "pass","fail"->{n.putBoolean("DebugApproval",true);TycoonAgency.finish(p,TycoonRooms.survey(p),"Operator test "+action,action.equals("pass"));}case "capacity"->result=TycoonRooms.survey(p).toString();case "cooldown"->n.putLong("PlacementAfter",h.clock());case "spawn"->result=testChild(p);case "reputation"->result="Agency reputation "+h.reputation();case "select"->{var nearest=p.serverLevel().getEntitiesOfClass(TycoonNpc.class,p.getBoundingBox().inflate(16),a->!a.staff()&&p.getUUID().equals(a.owner)).stream().min(Comparator.comparingDouble(p::distanceToSqr));if(nearest.isPresent()){n.putUUID("DebugSelected",nearest.get().resident);result="Selected "+nearest.get().resident;}else result="No owned resident nearby.";}
        case "traits"->result=r==null?"Select a resident first.":r.n.getCompound("Traits").toString();case "task"->result=r==null?"Select a resident first.":r.n.toString();case "hunger","meal"->{if(r!=null)r.need("Hunger",10);}case "thirst","water"->{if(r!=null)r.need("Thirst",10);}case "neglect"->{if(r!=null)r.need("Neglect",76);}case "comfort"->{if(r==null||!r.n.getBoolean("DebugChild"))return "Select a test resident first.";r.n.putInt("DebugComfort",0);r.n.putLong("DebugComfortUntil",h.clock()+1200);result="Selected test resident has zero comfort pressure for one active minute; furnishings unchanged.";}case "self_feed"->{if(r!=null){r.need("Hunger",20);r.n.putLong("MealRequest",h.clock()-2000);}}
        case "empty_fridge"->{for(var at:TycoonRooms.survey(p).furniture().getOrDefault("orphan_fridge",List.of())){var be=(TycoonBlockEntity)p.server.overworld().getBlockEntity(at);for(int i=0;i<be.getContainerSize();i++)if(!be.getItem(i).isEmpty()){if(p.getInventory().getFreeSlot()<0)return "Inventory full; remaining real food left intact.";p.getInventory().setItem(p.getInventory().getFreeSlot(),be.removeItem(i,64));}}}
        case "catch","item"->{if(r!=null){r.n.putString("Request",action.equals("catch")?"CATCH":"ITEM");r.n.putString("Wanted","minecraft:paper");r.n.putBoolean("Accepted",false);r.n.putLong("RequestExpires",h.clock()+1200);}}case "incident"->{if(r!=null)r.n.putLong("NextIncident",0);}case "forgive","punish"->{if(r!=null)result=TycoonCare.respond(p,r.id,action);}case "runaway"->{if(r!=null&&r.n.getBoolean("DebugChild"))r.need("Neglect",100);else return "Destructive outcome control is restricted to test residents.";}case "custody"->{for(var child:h.residents.values())if(child.n.getBoolean("DebugChild"))TycoonCare.depart(p,child,"AGENCY_CUSTODY");}case "critical"->{if(r!=null&&r.n.getBoolean("DebugChild")){r.need("Hunger",0);r.need("Thirst",0);r.n.putInt("CriticalTicks",23980);}else return "Severe-failure test is restricted to test residents.";}
        case "reset_platform"->{if(!n.getBoolean("DebugActivation"))return "Only a debugger-activated test platform may be repaired here. Normal worlds are never reset.";result=TycoonWorld.prepare(p)?"Restored missing generated platform cells/central objects; existing construction preserved.":"No safe repair available.";}
        case "relocate_test"->result=relocate(p);
        case "schedule"->{if(r==null||!r.n.getBoolean("DebugChild"))return "Select a test resident first.";r.n.putLong("DebugSleepUntil",h.clock()+200);result="Selected test resident will physically seek their assigned bed for ten seconds. World time unchanged.";}
        case "persistence"->{try{result=TycoonCheckpoints.home(p)?"Durable owner file saved and independently read back exactly. Process restart remains a separate check.":"Owner disk checkpoint mismatch.";}catch(java.io.IOException failure){result="Checkpoint failed: "+failure.getMessage();}}
        case "reset_simulation"->{int checked=0;for(var stack:p.getInventory().items)if(!stack.isEmpty()&&(TycoonWorld.owned(p,stack)||stack.is(TycoonContent.VOID_POWER.get())||stack.is(TycoonContent.SOUL_ESSENCE.get()))){var copy=stack.copy();var before=copy.save(new CompoundTag());com.coraline.feast.MainStoryRebirth.retireStack(copy,p.getUUID(),UUID.randomUUID(),0);if(!before.equals(copy.save(new CompoundTag())))return "FAIL: permanent item retired in reset simulation.";checked++;}result="Actual story inventory-retirement routine preserved "+checked+" permanent stack copies. No live story reset performed.";}
        case "preserved"->result="Permanent world="+h.active()+", region="+h.slot+", XP="+h.xp()+", soul="+n.getLong("SoulEssence")+", residents="+h.residents.size()+". Native QA also invokes the real committed MainStoryRebirth.reset boundary.";
        case "duplicates"->{var actors=p.server.overworld().getEntitiesOfClass(TycoonNpc.class,p.getBoundingBox().inflate(64),a->p.getUUID().equals(a.owner)&&!a.staff());var ids=new HashSet<UUID>();int duplicate=0,noncanonical=0;for(var actor:actors){if(!ids.add(actor.resident))duplicate++;var row=h.residents.get(actor.resident);if(row==null||!row.n.hasUUID("Entity")||!actor.getUUID().equals(row.n.getUUID("Entity")))noncanonical++;}result="Nearby canonical IDs "+ids.size()+", duplicates "+duplicate+", noncanonical entities "+noncanonical+"; active records "+h.activeResidents()+". Owner "+h.owner;}
        default->{return "Unknown debug action.";}}
        TycoonWorld.dirty(p);return result;
    }
    private static String relocate(ServerPlayer p){var h=TycoonWorld.home(p);var old=h.entrance();if(old==null||p.serverLevel()!=p.server.overworld())return "Stand in the Overworld with a placed owned entrance.";var target=old.east(2);var bed=TycoonWorld.registeredBed(p);if(bed==null||bed.distSqr(target)>Math.pow(TycoonConfig.BED_RADIUS.get(),2)||!TycoonWorld.safeFeet(p.serverLevel(),target)||!p.serverLevel().getBlockState(target).isAir())return "Two-block relocation target blocked/outside registered-bed radius. Nothing moved.";if(!TycoonWorld.pickup(p,old))return "Pickup blocked; free an inventory slot.";for(var stack:p.getInventory().items)if(stack.is(TycoonContent.DOOR.get().asItem())&&TycoonWorld.canPlace(p,"special_dimension_little_door",target,stack)){var previous=p.getMainHandItem();p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,stack);var context=new net.minecraft.world.item.context.BlockPlaceContext(p,net.minecraft.world.InteractionHand.MAIN_HAND,stack,new net.minecraft.world.phys.BlockHitResult(target.below().getCenter(),net.minecraft.core.Direction.UP,target.below(),false));var result=((BlockItem)stack.getItem()).place(context);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,previous);return result.consumesAction()?"Entrance moved to "+target.toShortString()+"; personal world preserved.":"Placement refused; entrance item remains in inventory.";}return "Entrance safely picked up; place the owned item manually.";}
    private static String testChild(ServerPlayer p){var h=TycoonWorld.home(p);if(h.entrance()==null||p.serverLevel()!=p.server.overworld())return "Place your Overworld entrance first.";var beds=TycoonRooms.survey(p).beds().stream().filter(b->h.residents.values().stream().noneMatch(r->r.active()&&b.equals(r.bed()))).toList();if(beds.isEmpty())return "A real safe unoccupied Orphan Bed is required even for the test.";var at=TycoonWorld.landing(p.server.overworld(),h.entrance());if(at==null)return "Arrival blocked.";var id=UUID.randomUUID();var r=TycoonCare.generate(id);var actor=TycoonContent.NPC.get().create(p.server.overworld());actor.configure(p.getUUID(),id,false,r.n.getInt("Appearance"));actor.setPos(at.getCenter());if(!p.server.overworld().addFreshEntity(actor))return "Spawn failed.";r.n.putBoolean("DebugChild",true);r.n.putString("Status","ACTIVE");r.n.putLong("Bed",beds.get(0).asLong());r.n.putUUID("Entity",actor.getUUID());r.n.putLong("ArrivedAt",h.clock());h.residents.put(id,r);h.state.putUUID("DebugSelected",id);return "Test resident spawned; no fee/cooldown/normal reward altered.";}
}
